22 |     /// @notice Stake ETH against multiple BLS keys within multiple LSDNs and specify the amount of ETH being supplied for each key
23 |     /// @dev Uses contract balance for funding and get Staking Funds Vault LP in exchange for ETH
24 |     /// @param _stakingFundsVault List of mev and fees vaults being interacted with
25 |     /// @param _ETHTransactionAmounts ETH being attached to each savETH vault in the list
26 |     /// @param _blsPublicKeyOfKnots For every staking funds vault, the list of BLS keys of LSDN validators receiving funding
27 |     /// @param _amounts List of amounts of ETH being staked per BLS public key
28 |     function batchDepositETHForStaking(
29 |         address[] calldata _stakingFundsVault,
30 |         uint256[] calldata _ETHTransactionAmounts,
31 |         bytes[][] calldata _blsPublicKeyOfKnots,
32 |         uint256[][] calldata _amounts
33 |     ) external {
34 |         uint256 numOfVaults = _stakingFundsVault.length;
