10 | contract GiantPoolBase is ReentrancyGuard {
11 | 
12 |     /// @notice Emitted when an account deposits Ether into the giant pool
13 |     event ETHDeposited(address indexed sender, uint256 amount);
14 | 
15 |     /// @notice Emitted when giant LP is burnt to recover ETH
16 |     event LPBurnedForETH(address indexed sender, uint256 amount);
17 | 
18 |     /// @notice Emitted when giant LP is burnt to receive LP from a specific vault
19 |     event LPSwappedForVaultLP(address indexed vaultLPToken, address indexed sender, uint256 amount);
20 | 
21 |     /// @notice Minimum amount of Ether that can be deposited into the contract
22 |     uint256 public constant MIN_STAKING_AMOUNT = 0.001 ether;
23 | 
24 |     /// @notice Total amount of ETH sat idle ready for either withdrawal or depositing into a liquid staking network
25 |     uint256 public idleETH;
26 | 
27 |     /// @notice LP token representing all ETH deposited and any ETH converted into savETH vault LP tokens from any liquid staking network
28 |     GiantLP public lpTokenETH;
29 | 
30 |     /// @notice Address of the liquid staking derivative factory that provides a source of truth on individual networks that can be funded
31 |     LSDNFactory public liquidStakingDerivativeFactory;
32 | 
33 |     /// @notice Add ETH to the ETH LP pool at a rate of 1:1. LPs can always pull out at same rate.
34 |     function depositETH(uint256 _amount) public payable {
35 |         require(msg.value >= MIN_STAKING_AMOUNT, "Minimum not supplied");
36 |         require(msg.value == _amount, "Value equal to amount");
37 | 
38 |         // The ETH capital has not yet been deployed to a liquid staking network
39 |         idleETH += msg.value;
40 | 
41 |         // Mint giant LP at ratio of 1:1
42 |         lpTokenETH.mint(msg.sender, msg.value);
43 | 
44 |         // If anything extra needs to be done
45 |         _onDepositETH();
46 | 
47 |         emit ETHDeposited(msg.sender, msg.value);
48 |     }
49 | 
50 |     /// @notice Allow a user to chose to burn their LP tokens for ETH only if the requested amount is idle and available from the contract
51 |     /// @param _amount of LP tokens user is burning in exchange for same amount of ETH
52 |     function withdrawETH(uint256 _amount) external nonReentrant {
53 |         require(_amount >= MIN_STAKING_AMOUNT, "Invalid amount");
54 |         require(lpTokenETH.balanceOf(msg.sender) >= _amount, "Invalid balance");
55 |         require(idleETH >= _amount, "Come back later or withdraw less ETH");
56 | 
57 |         idleETH -= _amount;
58 | 
59 |         lpTokenETH.burn(msg.sender, _amount);
60 |         (bool success,) = msg.sender.call{value: _amount}("");
61 |         require(success, "Failed to transfer ETH");
62 | 
63 |         emit LPBurnedForETH(msg.sender, _amount);
64 |     }
