 6 | abstract contract SyndicateRewardsProcessor {
 7 | 
 8 |     /// @notice Emitted when ETH is received by the contract and processed
 9 |     event ETHReceived(uint256 amount);
10 | 
11 |     /// @notice Emitted when ETH from syndicate is distributed to a user
12 |     event ETHDistributed(address indexed user, address indexed recipient, uint256 amount);
13 | 
14 |     /// @notice Precision used in rewards calculations for scaling up and down
15 |     uint256 public constant PRECISION = 1e24;
16 | 
17 |     /// @notice Total accumulated ETH per share of LP<>KNOT that has minted derivatives scaled to 'PRECISION'
18 |     uint256 public accumulatedETHPerLPShare;
19 | 
20 |     /// @notice Total ETH claimed by all users of the contract
21 |     uint256 public totalClaimed;
22 | 
23 |     /// @notice Last total rewards seen by the contract
24 |     uint256 public totalETHSeen;
25 | 
26 |     /// @notice Total ETH claimed by a given address for a given token
27 |     mapping(address => mapping(address => uint256)) public claimed;
28 | 
29 |     /// @dev Internal logic for previewing accumulated ETH for an LP user
30 |     function _previewAccumulatedETH(
31 |         address _sender,
32 |         address _token,
33 |         uint256 _balanceOfSender,
34 |         uint256 _numOfShares,
35 |         uint256 _unclaimedETHFromSyndicate
36 |     ) internal view returns (uint256) {
37 |         if (_balanceOfSender > 0) {
38 |             uint256 claim = claimed[_sender][_token];
39 | 
40 |             uint256 received = totalRewardsReceived() + _unclaimedETHFromSyndicate;
41 |             uint256 unprocessed = received - totalETHSeen;
42 | 
43 |             uint256 newAccumulatedETH = accumulatedETHPerLPShare + ((unprocessed * PRECISION) / _numOfShares);
44 | 
45 |             return ((newAccumulatedETH * _balanceOfSender) / PRECISION) - claim;
46 |         }
47 |         return 0;
48 |     }
