50 |     /// @dev Any due rewards from node running can be distributed to msg.sender if they have an LP balance
51 |     function _distributeETHRewardsToUserForToken(
52 |         address _user,
53 |         address _token,
54 |         uint256 _balance,
55 |         address _recipient
56 |     ) internal {
57 |         require(_recipient != address(0), "Zero address");
58 |         uint256 balance = _balance;
59 |         if (balance > 0) {
